#include <iostream>
#include <string_view>
#include <array>

int main() {
    int year = 0;
    int month = 0;
    int day = 0;

    if (!(std::cin >> year >> month >> day)) {
        return 1;
    }

    // Zeller's adjustment for January and February
    int m = month;
    int y = year;
    if (m == 1) {
        m = 13;
        y -= 1;
    } else if (m == 2) {
        m = 14;
        y -= 1;
    }

    int q = day;
    int j = y / 100;
    int k = y % 100;

    int h = (q + (26 * (m + 1)) / 10 + k + k / 4 + j / 4 + 5 * j) % 7;

    constexpr std::array<std::string_view, 7> days = {
        "Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday"
    };

    std::cout << "Day of the week is " << days[h] << "\n";
    return 0;
}

#include <iostream>

int main() {
    int number = 0;
    if (!(std::cin >> number)) {
        return 1;
    }

    int first_digit = number / 100;
    int last_digit = number % 10;

    if (first_digit == last_digit) {
        std::cout << number << " is a palindrome\n";
    } else {
        std::cout << number << " is not a palindrome\n";
    }

    return 0;
}
